package main

import (
	"fmt"
	"sort"
)

func main() {
	m := map[string]int{"banana": 3, "apple": 5, "cherry": 1}
	keys := make([]string, 0, len(m))
	for k := range m { // random order
		keys = append(keys, k)
	}
	sort.Strings(keys) // impose a deterministic order
	for _, k := range keys {
		fmt.Printf("%s=%d\n", k, m[k])
	}
	// Output: apple=5
	// banana=3
	// cherry=1
}

