package main

import (
	"fmt"
	"strings"
)

func main() {
	text := "go go gopher go"
	counts := make(map[string]int)
	for _, w := range strings.Fields(text) {
		counts[w]++ // missing key reads as 0, then increments
	}
	total := 0
	for _, c := range counts {
		total += c // summing is order-independent
	}
	fmt.Println("distinct:", len(counts), "total:", total)
}

